-- ============================================================================
-- PO-1C.1 — Comprehensive Exam Simulator Database Foundation
--
-- Database-only slice.
-- No question-bank import, attempt-generation runtime, simulator UI, or
-- readiness adapter is included here.
--
-- NOTE: The local Supabase CLI was unavailable in the execution environment,
-- so this timestamped migration filename follows the repository's existing
-- migration convention rather than being generated by "supabase migration new".
--
-- Invariants:
--   * comprehensive exams are separate from chapter quiz_attempts
--   * exactly 100 scored + 10 unscored questions per standard configuration
--   * current NIC-style scored blueprint is 35/10/40/15
--   * answer keys are never directly readable by ordinary authenticated users
--   * direct authenticated mutation is prohibited
--   * one active attempt per student/configuration
--   * PO-1B receives a distinct comprehensive_exam telemetry surface
--   * exam/telemetry time never writes H&A/attendance-hour state
-- ============================================================================

create extension if not exists "pgcrypto";

-- ============================================================================
-- 1. VERSIONED EXAM CONFIGURATION
-- ============================================================================

create table if not exists public.comprehensive_exam_configs (
  id uuid primary key default gen_random_uuid(),
  slug text not null,
  version integer not null,
  title text not null,
  status text not null default 'draft',
  blueprint_version text not null,
  question_bank_version text not null,
  scoring_policy_version text not null,
  time_limit_seconds integer,
  passing_percentage integer,
  scored_question_count integer not null default 100,
  unscored_question_count integer not null default 10,
  created_at timestamptz not null default clock_timestamp(),
  updated_at timestamptz not null default clock_timestamp(),
  activated_at timestamptz,
  retired_at timestamptz,

  constraint comprehensive_exam_configs_version_check
    check (version > 0),
  constraint comprehensive_exam_configs_status_check
    check (status in ('draft','active','retired')),
  constraint comprehensive_exam_configs_time_limit_check
    check (time_limit_seconds is null or time_limit_seconds > 0),
  constraint comprehensive_exam_configs_passing_percentage_check
    check (passing_percentage is null or passing_percentage between 0 and 100),
  constraint comprehensive_exam_configs_scored_count_check
    check (scored_question_count = 100),
  constraint comprehensive_exam_configs_unscored_count_check
    check (unscored_question_count = 10),
  constraint comprehensive_exam_configs_lifecycle_check
    check (
      (status = 'draft' and activated_at is null and retired_at is null)
      or (status = 'active' and activated_at is not null and retired_at is null)
      or (status = 'retired' and activated_at is not null and retired_at is not null)
    )
);

create unique index if not exists uq_comprehensive_exam_configs_slug_version
  on public.comprehensive_exam_configs(slug, version);

create index if not exists idx_comprehensive_exam_configs_status
  on public.comprehensive_exam_configs(status, slug, version desc);

create unique index if not exists uq_comprehensive_exam_configs_active_slug
  on public.comprehensive_exam_configs(slug)
  where status = 'active';

create table if not exists public.comprehensive_exam_config_domains (
  config_id uuid not null references public.comprehensive_exam_configs(id) on delete cascade,
  domain text not null,
  weight_percent integer not null,
  scored_question_count integer not null,
  created_at timestamptz not null default clock_timestamp(),

  constraint comprehensive_exam_config_domains_domain_check
    check (
      domain in (
        'scientific_concepts',
        'implements_equipment',
        'hair_care_services',
        'facial_hair_skin_care_services'
      )
    ),
  constraint comprehensive_exam_config_domains_weight_check
    check (weight_percent > 0 and weight_percent <= 100),
  constraint comprehensive_exam_config_domains_question_count_check
    check (scored_question_count > 0 and scored_question_count <= 100),

  primary key (config_id, domain)
);

create index if not exists idx_comprehensive_exam_config_domains_config
  on public.comprehensive_exam_config_domains(config_id);

-- ============================================================================
-- 2. PRIVATE QUESTION REGISTRY + CONFIG ELIGIBILITY
-- ============================================================================

create table if not exists public.comprehensive_exam_questions (
  id uuid primary key default gen_random_uuid(),
  source_question_id text not null,
  source_kind text not null,
  source_chapter_id text,
  domain text not null,
  prompt text not null,
  option_a text not null,
  option_b text not null,
  option_c text not null,
  option_d text not null,
  correct_option text not null,
  explanation text not null,
  content_version text not null,
  provenance jsonb not null default '{}'::jsonb,
  status text not null default 'active',
  created_at timestamptz not null default clock_timestamp(),
  updated_at timestamptz not null default clock_timestamp(),

  constraint comprehensive_exam_questions_source_kind_check
    check (source_kind in ('chapter_quiz','comprehensive_bank','certified_original')),
  constraint comprehensive_exam_questions_domain_check
    check (
      domain in (
        'scientific_concepts',
        'implements_equipment',
        'hair_care_services',
        'facial_hair_skin_care_services'
      )
    ),
  constraint comprehensive_exam_questions_correct_option_check
    check (correct_option in ('a','b','c','d')),
  constraint comprehensive_exam_questions_status_check
    check (status in ('active','retired')),
  constraint comprehensive_exam_questions_provenance_object_check
    check (jsonb_typeof(provenance) = 'object')
);

create unique index if not exists uq_comprehensive_exam_questions_source_id
  on public.comprehensive_exam_questions(source_question_id);

create index if not exists idx_comprehensive_exam_questions_domain_status
  on public.comprehensive_exam_questions(domain, status);

create index if not exists idx_comprehensive_exam_questions_content_version
  on public.comprehensive_exam_questions(content_version);

create table if not exists public.comprehensive_exam_config_questions (
  config_id uuid not null references public.comprehensive_exam_configs(id) on delete cascade,
  question_id uuid not null references public.comprehensive_exam_questions(id) on delete restrict,
  scored_eligible boolean not null default true,
  unscored_eligible boolean not null default true,
  is_active boolean not null default true,
  created_at timestamptz not null default clock_timestamp(),

  constraint comprehensive_exam_config_questions_eligibility_check
    check (not is_active or scored_eligible or unscored_eligible),

  primary key (config_id, question_id)
);

create index if not exists idx_comprehensive_exam_config_questions_scored
  on public.comprehensive_exam_config_questions(config_id, question_id)
  where is_active and scored_eligible;

create index if not exists idx_comprehensive_exam_config_questions_unscored
  on public.comprehensive_exam_config_questions(config_id, question_id)
  where is_active and unscored_eligible;

-- ============================================================================
-- 3. ATTEMPT LIFECYCLE / RESULT
-- ============================================================================

create table if not exists public.comprehensive_exam_attempts (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  school_id uuid not null references public.schools(id) on delete restrict,
  config_id uuid not null references public.comprehensive_exam_configs(id) on delete restrict,
  config_version integer not null,
  blueprint_version text not null,
  question_bank_version text not null,
  scoring_policy_version text not null,
  status text not null default 'active',
  started_at timestamptz not null,
  expires_at timestamptz not null,
  completed_at timestamptz,
  completion_reason text,
  elapsed_seconds integer,
  scored_correct integer,
  scored_total integer not null default 100,
  percentage integer,
  passed boolean,
  unscored_correct integer,
  unscored_total integer not null default 10,
  domain_breakdown jsonb not null default '{}'::jsonb,
  flagged_at_submit integer,
  unanswered_at_submit integer,
  attempt_number integer not null,
  previous_attempt_id uuid references public.comprehensive_exam_attempts(id) on delete set null,
  study_session_id uuid not null references public.study_sessions(id) on delete restrict,
  readiness_sync_status text not null default 'pending',
  created_at timestamptz not null default clock_timestamp(),
  updated_at timestamptz not null default clock_timestamp(),

  constraint comprehensive_exam_attempts_status_check
    check (status in ('active','completed','expired','recovered_finalized','voided')),
  constraint comprehensive_exam_attempts_completion_reason_check
    check (
      completion_reason is null
      or completion_reason in (
        'student_submit',
        'timer_expired',
        'recovered_finalize',
        'administrative_void'
      )
    ),
  constraint comprehensive_exam_attempts_time_check
    check (expires_at > started_at),
  constraint comprehensive_exam_attempts_elapsed_check
    check (elapsed_seconds is null or elapsed_seconds >= 0),
  constraint comprehensive_exam_attempts_scored_total_check
    check (scored_total = 100),
  constraint comprehensive_exam_attempts_scored_correct_check
    check (scored_correct is null or scored_correct between 0 and 100),
  constraint comprehensive_exam_attempts_percentage_check
    check (percentage is null or percentage between 0 and 100),
  constraint comprehensive_exam_attempts_unscored_total_check
    check (unscored_total = 10),
  constraint comprehensive_exam_attempts_unscored_correct_check
    check (unscored_correct is null or unscored_correct between 0 and 10),
  constraint comprehensive_exam_attempts_flagged_count_check
    check (flagged_at_submit is null or flagged_at_submit between 0 and 110),
  constraint comprehensive_exam_attempts_unanswered_count_check
    check (unanswered_at_submit is null or unanswered_at_submit between 0 and 110),
  constraint comprehensive_exam_attempts_attempt_number_check
    check (attempt_number > 0),
  constraint comprehensive_exam_attempts_readiness_status_check
    check (readiness_sync_status in ('pending','synced','failed')),
  constraint comprehensive_exam_attempts_domain_breakdown_object_check
    check (jsonb_typeof(domain_breakdown) = 'object'),
  constraint comprehensive_exam_attempts_lifecycle_check
    check (
      (
        status = 'active'
        and completed_at is null
        and completion_reason is null
        and elapsed_seconds is null
        and scored_correct is null
        and percentage is null
        and passed is null
        and unscored_correct is null
        and flagged_at_submit is null
        and unanswered_at_submit is null
      )
      or (
        status in ('completed','expired','recovered_finalized')
        and completed_at is not null
        and completion_reason is not null
        and elapsed_seconds is not null
        and scored_correct is not null
        and percentage is not null
        and passed is not null
        and unscored_correct is not null
        and flagged_at_submit is not null
        and unanswered_at_submit is not null
      )
      or (
        status = 'voided'
        and completed_at is not null
        and completion_reason = 'administrative_void'
      )
    )
);

create index if not exists idx_comprehensive_exam_attempts_user_started
  on public.comprehensive_exam_attempts(user_id, started_at desc);

create index if not exists idx_comprehensive_exam_attempts_school_started
  on public.comprehensive_exam_attempts(school_id, started_at desc);

create index if not exists idx_comprehensive_exam_attempts_school_user_started
  on public.comprehensive_exam_attempts(school_id, user_id, started_at desc);

create index if not exists idx_comprehensive_exam_attempts_config_started
  on public.comprehensive_exam_attempts(config_id, started_at desc);

create index if not exists idx_comprehensive_exam_attempts_status_expires
  on public.comprehensive_exam_attempts(status, expires_at);

create unique index if not exists uq_comprehensive_exam_attempt_active_user_config
  on public.comprehensive_exam_attempts(user_id, config_id)
  where status = 'active';

create unique index if not exists uq_comprehensive_exam_attempt_number
  on public.comprehensive_exam_attempts(user_id, config_id, attempt_number);

create unique index if not exists uq_comprehensive_exam_attempt_study_session
  on public.comprehensive_exam_attempts(study_session_id);

-- ============================================================================
-- 4. ATTEMPT QUESTION SNAPSHOTS / ANSWERS / FLAGS
-- ============================================================================

create table if not exists public.comprehensive_exam_attempt_items (
  id uuid primary key default gen_random_uuid(),
  attempt_id uuid not null references public.comprehensive_exam_attempts(id) on delete cascade,
  question_id uuid not null references public.comprehensive_exam_questions(id) on delete restrict,
  position smallint not null,
  domain text not null,
  is_scored boolean not null,
  prompt_snapshot text not null,
  option_a_snapshot text not null,
  option_b_snapshot text not null,
  option_c_snapshot text not null,
  option_d_snapshot text not null,
  correct_option_snapshot text not null,
  explanation_snapshot text not null,
  selected_option text,
  answered_at timestamptz,
  flagged boolean not null default false,
  flag_updated_at timestamptz,
  created_at timestamptz not null default clock_timestamp(),
  updated_at timestamptz not null default clock_timestamp(),

  constraint comprehensive_exam_attempt_items_position_check
    check (position between 1 and 110),
  constraint comprehensive_exam_attempt_items_domain_check
    check (
      domain in (
        'scientific_concepts',
        'implements_equipment',
        'hair_care_services',
        'facial_hair_skin_care_services'
      )
    ),
  constraint comprehensive_exam_attempt_items_correct_option_check
    check (correct_option_snapshot in ('a','b','c','d')),
  constraint comprehensive_exam_attempt_items_selected_option_check
    check (selected_option is null or selected_option in ('a','b','c','d')),
  constraint comprehensive_exam_attempt_items_answered_state_check
    check (
      (selected_option is null and answered_at is null)
      or (selected_option is not null and answered_at is not null)
    )
);

create unique index if not exists uq_comprehensive_exam_attempt_items_position
  on public.comprehensive_exam_attempt_items(attempt_id, position);

create unique index if not exists uq_comprehensive_exam_attempt_items_question
  on public.comprehensive_exam_attempt_items(attempt_id, question_id);

create index if not exists idx_comprehensive_exam_attempt_items_attempt_flagged
  on public.comprehensive_exam_attempt_items(attempt_id, flagged, position);

create index if not exists idx_comprehensive_exam_attempt_items_attempt_answered
  on public.comprehensive_exam_attempt_items(attempt_id, answered_at, position);

create index if not exists idx_comprehensive_exam_attempt_items_domain
  on public.comprehensive_exam_attempt_items(attempt_id, domain, is_scored);

-- ============================================================================
-- 5. APPEND-ONLY OPERATIONAL / INTEGRITY EVENTS
-- ============================================================================

create table if not exists public.comprehensive_exam_attempt_events (
  id uuid primary key default gen_random_uuid(),
  attempt_id uuid not null references public.comprehensive_exam_attempts(id) on delete cascade,
  user_id uuid not null references auth.users(id) on delete cascade,
  school_id uuid not null references public.schools(id) on delete restrict,
  event_type text not null,
  item_id uuid references public.comprehensive_exam_attempt_items(id) on delete set null,
  received_at timestamptz not null default clock_timestamp(),
  metadata jsonb not null default '{}'::jsonb,

  constraint comprehensive_exam_attempt_events_event_type_check
    check (
      event_type in (
        'attempt_started',
        'attempt_resumed',
        'answer_saved',
        'flag_set',
        'flag_cleared',
        'review_opened',
        'focus_lost',
        'focus_gained',
        'submitted',
        'expired',
        'recovered_finalized',
        'telemetry_end_failed',
        'readiness_sync_failed',
        'readiness_synced',
        'voided'
      )
    ),
  constraint comprehensive_exam_attempt_events_metadata_object_check
    check (jsonb_typeof(metadata) = 'object')
);

create index if not exists idx_comprehensive_exam_attempt_events_attempt_received
  on public.comprehensive_exam_attempt_events(attempt_id, received_at);

create index if not exists idx_comprehensive_exam_attempt_events_user_received
  on public.comprehensive_exam_attempt_events(user_id, received_at desc);

create index if not exists idx_comprehensive_exam_attempt_events_school_received
  on public.comprehensive_exam_attempt_events(school_id, received_at desc);

