create trigger comprehensive_exam_configs_updated_at
  before update on public.comprehensive_exam_configs
  for each row execute function public.update_updated_at_column();

drop trigger if exists comprehensive_exam_questions_updated_at
  on public.comprehensive_exam_questions;
create trigger comprehensive_exam_questions_updated_at
  before update on public.comprehensive_exam_questions
  for each row execute function public.update_updated_at_column();

drop trigger if exists comprehensive_exam_attempts_updated_at
  on public.comprehensive_exam_attempts;
create trigger comprehensive_exam_attempts_updated_at
  before update on public.comprehensive_exam_attempts
  for each row execute function public.update_updated_at_column();

drop trigger if exists comprehensive_exam_attempt_items_updated_at
  on public.comprehensive_exam_attempt_items;
create trigger comprehensive_exam_attempt_items_updated_at
  before update on public.comprehensive_exam_attempt_items
  for each row execute function public.update_updated_at_column();

-- ============================================================================
-- 7. PO-1B TELEMETRY SURFACE EXTENSION
-- ============================================================================

alter table public.study_sessions
  drop constraint if exists study_sessions_surface_type_check;

alter table public.study_sessions
  add constraint study_sessions_surface_type_check
  check (
    surface_type in (
      'lesson',
      'flashcards',
      'quiz',
      'remediation',
      'reassessment',
      'comprehensive_exam'
    )
  );

alter table public.study_session_events
  drop constraint if exists study_session_events_surface_type_check;

alter table public.study_session_events
  add constraint study_session_events_surface_type_check
  check (
    surface_type in (
      'lesson',
      'flashcards',
      'quiz',
      'remediation',
      'reassessment',
      'comprehensive_exam'
    )
  );

-- Extend the existing PO-1B session-opening boundary so later PO-1C runtime
-- can open a zero-credit comprehensive exam study session without creating a
-- second telemetry system.
create or replace function public.begin_study_session(
  p_surface_type text,
  p_surface_id text default null
)
returns uuid
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_user_id uuid := auth.uid();
  v_profile record;
  v_session_id uuid;
begin
  if v_user_id is null then
    raise exception 'Authentication required';
  end if;

  select role, school_id, coalesce(is_disabled, false) as is_disabled, approval_status
    into v_profile
  from public.profiles
  where id = v_user_id
  limit 1;

  if not found then
    raise exception 'Profile not found';
  end if;

  if v_profile.role not in ('student', 'apprentice') then
    raise exception 'Learner role required';
  end if;

  if v_profile.school_id is null then
    raise exception 'School assignment required';
  end if;

  if v_profile.is_disabled or coalesce(v_profile.approval_status, '') <> 'approved' then
    raise exception 'Active approved learner account required';
  end if;

  if p_surface_type not in (
    'lesson',
    'flashcards',
    'quiz',
    'remediation',
    'reassessment',
    'comprehensive_exam'
  ) then
    raise exception 'Unsupported study surface';
  end if;

  insert into public.study_sessions (
    user_id,
    school_id,
    surface_type,
    surface_id
  )
  values (
    v_user_id,
    v_profile.school_id,
    p_surface_type,
    nullif(btrim(p_surface_id), '')
  )
  returning id into v_session_id;

  return v_session_id;
end;
$$;

revoke execute on function public.begin_study_session(text, text) from public, anon;
grant execute on function public.begin_study_session(text, text) to authenticated;
grant execute on function public.begin_study_session(text, text) to service_role;

-- ============================================================================
-- 8. ROW LEVEL SECURITY
-- ============================================================================

alter table public.comprehensive_exam_configs enable row level security;
alter table public.comprehensive_exam_config_domains enable row level security;
alter table public.comprehensive_exam_questions enable row level security;
alter table public.comprehensive_exam_config_questions enable row level security;
alter table public.comprehensive_exam_attempts enable row level security;
alter table public.comprehensive_exam_attempt_items enable row level security;
alter table public.comprehensive_exam_attempt_events enable row level security;

-- Configuration/question-bank tables remain private in PO-1C.1.
-- Safe projections arrive through later RPCs; no direct authenticated SELECT
-- is granted here.

-- Attempt summaries are safe for direct read under RLS.
drop policy if exists comprehensive_exam_attempts_student_select
  on public.comprehensive_exam_attempts;
create policy comprehensive_exam_attempts_student_select
  on public.comprehensive_exam_attempts
  for select to authenticated
  using ((select auth.uid()) = user_id);

drop policy if exists comprehensive_exam_attempts_school_staff_select
  on public.comprehensive_exam_attempts;
create policy comprehensive_exam_attempts_school_staff_select
  on public.comprehensive_exam_attempts
  for select to authenticated
  using (
    public.is_school_staff(school_id)
    and public.user_school_id(user_id) = school_id
  );

drop policy if exists comprehensive_exam_attempts_platform_admin_select
  on public.comprehensive_exam_attempts;
create policy comprehensive_exam_attempts_platform_admin_select
  on public.comprehensive_exam_attempts
  for select to authenticated
  using (public.is_platform_admin());

-- ============================================================================
-- 9. MINIMUM PRIVILEGES
-- ============================================================================

revoke all on public.comprehensive_exam_configs from anon, authenticated;
revoke all on public.comprehensive_exam_config_domains from anon, authenticated;
revoke all on public.comprehensive_exam_questions from anon, authenticated;
revoke all on public.comprehensive_exam_config_questions from anon, authenticated;
revoke all on public.comprehensive_exam_attempts from anon, authenticated;
revoke all on public.comprehensive_exam_attempt_items from anon, authenticated;
revoke all on public.comprehensive_exam_attempt_events from anon, authenticated;

grant select on public.comprehensive_exam_attempts to authenticated;

grant select, insert, update, delete
  on public.comprehensive_exam_configs,
     public.comprehensive_exam_config_domains,
     public.comprehensive_exam_questions,
     public.comprehensive_exam_config_questions,
     public.comprehensive_exam_attempts,
     public.comprehensive_exam_attempt_items,
     public.comprehensive_exam_attempt_events
  to service_role;

-- ============================================================================
-- 10. CONFIGURATION ACTIVATION BOUNDARY
-- ============================================================================
-- Activating a configuration is privileged. This function validates:
--   * exact 100/10 standard counts
--   * exact four-domain 35/10/40/15 blueprint
--   * time limit + passing threshold are configured
--   * each scored domain has sufficient active eligible inventory
--   * there is enough unscored capacity to preserve ten unique pilot items
--
-- This does NOT import question content. Until PO-1C.2 populates the registry
-- and config mappings, activation correctly fails closed.

create or replace function public.activate_comprehensive_exam_config(
  p_config_id uuid
)
returns void
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_config public.comprehensive_exam_configs%rowtype;
  v_domain_count integer;
  v_weight_total integer;
  v_scored_total integer;
  v_bad_domain_rows integer;
  v_scientific_count integer;
  v_implements_count integer;
  v_hair_count integer;
  v_facial_count integer;
  v_unscored_capacity integer;
begin
  if auth.uid() is null then
    raise exception 'Authentication required';
  end if;

  if not public.is_platform_admin() then
    raise exception 'Platform admin required';
  end if;

  select *
    into v_config
  from public.comprehensive_exam_configs
  where id = p_config_id
  for update;

  if not found then
    raise exception 'Exam configuration not found';
  end if;

  if v_config.status <> 'draft' then
    raise exception 'Only draft configurations can be activated';
  end if;

  if v_config.time_limit_seconds is null or v_config.time_limit_seconds <= 0 then
    raise exception 'Exam time limit must be configured before activation';
  end if;

  if v_config.passing_percentage is null
     or v_config.passing_percentage < 0
     or v_config.passing_percentage > 100 then
    raise exception 'Passing percentage must be configured before activation';
  end if;

  if v_config.scored_question_count <> 100
     or v_config.unscored_question_count <> 10 then
    raise exception 'Standard comprehensive exam must be 100 scored + 10 unscored';
  end if;

  select
    count(*),
    coalesce(sum(weight_percent), 0),
    coalesce(sum(scored_question_count), 0),
    count(*) filter (
      where not (
        (domain = 'scientific_concepts' and weight_percent = 35 and scored_question_count = 35)
        or (domain = 'implements_equipment' and weight_percent = 10 and scored_question_count = 10)
        or (domain = 'hair_care_services' and weight_percent = 40 and scored_question_count = 40)
        or (domain = 'facial_hair_skin_care_services' and weight_percent = 15 and scored_question_count = 15)
      )
    )
  into
    v_domain_count,
    v_weight_total,
    v_scored_total,
    v_bad_domain_rows
  from public.comprehensive_exam_config_domains
  where config_id = p_config_id;

  if v_domain_count <> 4
     or v_weight_total <> 100
     or v_scored_total <> 100
     or v_bad_domain_rows <> 0 then
    raise exception 'Configuration must use the exact 35/10/40/15 scored blueprint';
  end if;

  select
    count(*) filter (where q.domain = 'scientific_concepts'),
    count(*) filter (where q.domain = 'implements_equipment'),
    count(*) filter (where q.domain = 'hair_care_services'),
    count(*) filter (where q.domain = 'facial_hair_skin_care_services')
  into
    v_scientific_count,
    v_implements_count,
    v_hair_count,
    v_facial_count
  from public.comprehensive_exam_config_questions cq
  join public.comprehensive_exam_questions q
    on q.id = cq.question_id
  where cq.config_id = p_config_id
    and cq.is_active
    and cq.scored_eligible
    and q.status = 'active';

  if v_scientific_count < 35
     or v_implements_count < 10
     or v_hair_count < 40
     or v_facial_count < 15 then
    raise exception 'Insufficient scored question inventory for configured blueprint';
  end if;

  -- Maximum number of unique unscored items that can be reserved without
  -- making any scored domain fall below its required quota.
  with domain_inventory as (
    select
      q.domain,
      count(*) filter (where cq.scored_eligible) as scored_pool,
      count(*) filter (where cq.unscored_eligible and not cq.scored_eligible) as unscored_only,
      count(*) filter (where cq.unscored_eligible and cq.scored_eligible) as both_pool
    from public.comprehensive_exam_config_questions cq
    join public.comprehensive_exam_questions q
      on q.id = cq.question_id
    where cq.config_id = p_config_id
      and cq.is_active
      and q.status = 'active'
    group by q.domain
  ),
  with_quota as (
    select
      domain,
      scored_pool,
      unscored_only,
      both_pool,
      case domain
        when 'scientific_concepts' then 35
        when 'implements_equipment' then 10
        when 'hair_care_services' then 40
        when 'facial_hair_skin_care_services' then 15
        else 1000000
      end as quota
    from domain_inventory
  )
  select coalesce(sum(
    unscored_only
    + least(both_pool, greatest(scored_pool - quota, 0))
  ), 0)
  into v_unscored_capacity
  from with_quota;

  if v_unscored_capacity < 10 then
    raise exception 'Insufficient unique unscored capacity after preserving scored quotas';
  end if;

  -- Keep only one active version for the same slug.
  update public.comprehensive_exam_configs
  set
    status = 'retired',
    retired_at = clock_timestamp()
  where slug = v_config.slug
    and status = 'active'
    and id <> p_config_id;

  update public.comprehensive_exam_configs
  set
    status = 'active',
    activated_at = clock_timestamp(),
    retired_at = null
  where id = p_config_id;
end;
$$;

revoke execute on function public.activate_comprehensive_exam_config(uuid)
  from public, anon;
grant execute on function public.activate_comprehensive_exam_config(uuid)
  to authenticated;
grant execute on function public.activate_comprehensive_exam_config(uuid)
  to service_role;

